strip_html <- function(x) {
  if (is.null(x) || length(x) == 0 || is.na(x)) return("")
  s <- gsub("<[^>]*>", " ", as.character(x))
  s <- gsub("&gt;", ">", s, fixed = TRUE)
  s <- gsub("&lt;", "<", s, fixed = TRUE)
  s <- gsub("&amp;", "&", s, fixed = TRUE)
  gsub("^[[:space:]]+|[[:space:]]+$", "", gsub("[[:space:]]+", " ", s))
}

row_by_key <- function(df, key) {
  sub <- df[gsub('^"|"$', "", rownames(df)) == key, , drop = FALSE]
  if (nrow(sub) != 1L) stop(sprintf("Expected 1 row for key '%s', got %d", key, nrow(sub)))
  sub
}

stb_internal <- function(nm) {
  if (exists(nm, mode = "any", inherits = TRUE)) {
    return(get(nm, inherits = TRUE))
  }
  for (pkg in c("ClinicoPath", "jjstatsplot")) {
    if (pkg %in% loadedNamespaces()) {
      ns <- asNamespace(pkg)
      if (exists(nm, envir = ns, inherits = FALSE)) return(get(nm, envir = ns, inherits = FALSE))
    }
  }
  stop(sprintf("Internal object '%s' not found", nm))
}

render_plot_obj <- function(res) {
  f <- tempfile(fileext = ".svg")
  if (requireNamespace("svglite", quietly = TRUE)) {
    svglite::svglite(f, width = 8, height = 6)
  } else {
    grDevices::pdf(f, width = 8, height = 6)
  }
  on.exit({
    try(grDevices::dev.off(), silent = TRUE)
    unlink(f)
  }, add = TRUE)
  print(res$plot)
  ggplot2::last_plot()
}

build_hand_fixture <- function() {
  df <- data.frame(
    `Gréade sc` = factor(
      c("Stage III", "Stage III", "Stage III", "Stage III",
        "Stage I",   "Stage I",   "Stage I",
        "Stage II",  "Stage II",  "Stage II"),
      levels = c("Stage III", "Stage I", "Stage II")
    ),
    resp = factor(
      c("High", "High", "Moderate", "Low",
        "High", "Moderate", "Low",
        "High", "Moderate", "Low"),
      levels = c("High", "Moderate", "Low")
    ),
    cnt = c(15, 15, 10, 10,
            10, 20, 20,
            20, 30, 50),
    check.names = FALSE,
    stringsAsFactors = FALSE
  )
  rownames(df) <- paste0("id_", c(10, 25, 3, 41, 52, 6, 77, 8, 91, 100))
  df
}

test_that("C01-C05: summary table matches closed-form category, segment, row, and total counts", {
  # Oracle: closed-form hand derivation on 3x3 contingency counts (N=10 rows, sum=200)
  df <- build_hand_fixture()
  res <- suppressWarnings(jjsegmentedtotalbar(
    data = df, x_var = "Gréade sc", y_var = "cnt", fill_var = "resp",
    y_is_count = TRUE, show_plot = FALSE
  ))
  tb_sum <- res$summary$asDF

  expect_equal(tb_sum$categories[1], 3L)
  expect_equal(tb_sum$segments[1], 3L)
  expect_equal(tb_sum$rows_analysed[1], 10L)
  expect_equal(tb_sum$total_observations[1], 200, tolerance = 1e-8)
  expect_equal(tb_sum$chart_type[1], "Segmented Total Bar (100% Stacked)")
})

test_that("C06-C10: composition_table matches closed-form within-category and overall proportions", {
  # Oracle: closed-form proportions p_{ij} = n_{ij}/n_{i+} and p^{(ovr)}_{ij} = n_{ij}/N
  df <- build_hand_fixture()
  res <- suppressWarnings(jjsegmentedtotalbar(
    data = df, x_var = "Gréade sc", y_var = "cnt", fill_var = "resp",
    sort_categories = "none", y_is_count = TRUE, show_plot = FALSE
  ))
  tb_comp <- res$composition_table$asDF
  r_first <- tb_comp[tb_comp$category == "Stage III" & tb_comp$segment == "High", ]
  r_mid   <- tb_comp[tb_comp$category == "Stage I"   & tb_comp$segment == "Moderate", ]
  r_last  <- tb_comp[tb_comp$category == "Stage II"  & tb_comp$segment == "Low", ]

  expect_equal(unique(tb_comp$category), c("Stage III", "Stage I", "Stage II"))
  expect_equal(c(r_first$count[1], r_mid$count[1], r_last$count[1]), c(30, 20, 50), tolerance = 1e-8)
  expect_equal(c(r_first$percentage[1], r_mid$percentage[1], r_last$percentage[1]), c(0.60, 0.40, 0.50), tolerance = 1e-8)
  expect_equal(c(r_first$overall_percentage[1], r_mid$overall_percentage[1], r_last$overall_percentage[1]), c(0.15, 0.10, 0.25), tolerance = 1e-8)
  expect_equal(c(r_first$total_in_category[1], r_last$total_in_category[1]), c(50, 100), tolerance = 1e-8)
})

