test_that("C16-C20: statistical_tests matches closed-form Pearson chi-square and Haberman (1973) residuals", {
  # Oracle: Pearson (1900) X^2 = 185/6 = 30.8333333333, df = 4; Haberman (1973) Biometrics 29:205-220 z_{1,1} = 15/sqrt(7.875)
  df <- build_hand_fixture()
  res <- suppressWarnings(jjsegmentedtotalbar(
    data = df, x_var = "Gréade sc", y_var = "cnt", fill_var = "resp",
    show_statistical_tests = TRUE, y_is_count = TRUE, show_plot = FALSE
  ))
  tb_st <- res$statistical_tests$asDF

  expect_equal(tb_st$statistic[1], 185 / 6, tolerance = 1e-8)
  expect_equal(tb_st$df[1], 4L)
  expect_equal(tb_st$p_value[1], stats::pchisq(185 / 6, df = 4, lower.tail = FALSE), tolerance = 1e-8)
  expect_equal(tb_st$interpretation[1], "Significant association between Gréade sc and resp (p < 0.05)")
  expect_equal(tb_st$statistic[2], 15 / sqrt(7.875), tolerance = 1e-8)
  expect_equal(tb_st$interpretation[2], "Highest positive association: Stage III \u2192 High")
})

test_that("C08, C09, C16, C18, C20: benchmark against datasets::HairEyeColor (Snee 1974) and stats::chisq.test", {
  # Oracle: datasets::HairEyeColor (Snee 1974 Am Stat 28:9-12) and stats::chisq.test(correct = FALSE)
  he_df <- as.data.frame(datasets::HairEyeColor, stringsAsFactors = FALSE)
  he_tab <- stats::xtabs(Freq ~ Hair + Eye, data = he_df)
  he_prop <- prop.table(he_tab, margin = 1)
  he_ovr <- prop.table(he_tab)
  he_chi <- suppressWarnings(stats::chisq.test(he_tab, correct = FALSE))

  res <- suppressWarnings(jjsegmentedtotalbar(
    data = he_df, x_var = "Hair", y_var = "Freq", fill_var = "Eye",
    show_statistical_tests = TRUE, y_is_count = TRUE, show_plot = FALSE
  ))
  c_df <- res$composition_table$asDF
  t_df <- res$statistical_tests$asDF

  row_bb <- c_df[c_df$category == "Black" & c_df$segment == "Brown", ]
  row_bl <- c_df[c_df$category == "Blond" & c_df$segment == "Blue", ]

  expect_equal(row_bb$percentage[1], as.numeric(he_prop["Black", "Brown"]), tolerance = 1e-8)
  expect_equal(row_bl$percentage[1], as.numeric(he_prop["Blond", "Blue"]), tolerance = 1e-8)
  expect_equal(row_bl$overall_percentage[1], as.numeric(he_ovr["Blond", "Blue"]), tolerance = 1e-8)
  expect_equal(t_df$statistic[1], as.numeric(he_chi$statistic), tolerance = 1e-8)
  expect_equal(t_df$p_value[1], as.numeric(he_chi$p.value), tolerance = 1e-8)
  expect_equal(t_df$statistic[2], max(abs(he_chi$stdres)), tolerance = 1e-8)
})

