test_that("C08, C09, C16, C18, C20: algebraic invariants (permutation, relabelling, rescaling, duplication, transpose, faceting)", {
  # Oracle: mathematical invariants of contingency proportions and Pearson X^2
  df <- build_hand_fixture()
  res_base <- suppressWarnings(jjsegmentedtotalbar(
    data = df, x_var = "Gréade sc", y_var = "cnt", fill_var = "resp",
    show_statistical_tests = TRUE, y_is_count = TRUE, show_plot = FALSE
  ))
  c_base <- res_base$composition_table$asDF
  t_base <- res_base$statistical_tests$asDF

  # 1. Row permutation invariance
  set.seed(20261110)
  df_perm <- df[sample(nrow(df)), ]
  res_perm <- suppressWarnings(jjsegmentedtotalbar(
    data = df_perm, x_var = "Gréade sc", y_var = "cnt", fill_var = "resp",
    show_statistical_tests = TRUE, y_is_count = TRUE, show_plot = FALSE
  ))
  expect_equal(res_perm$composition_table$asDF$percentage, c_base$percentage, tolerance = 1e-8)
  expect_equal(res_perm$statistical_tests$asDF$statistic[1], t_base$statistic[1], tolerance = 1e-8)

  # 2. Factor level relabelling invariance
  df_relab <- df
  levels(df_relab$`Gréade sc`) <- c("G_III", "G_I", "G_II")
  levels(df_relab$resp) <- c("Seg_H", "Seg_M", "Seg_L")
  res_relab <- suppressWarnings(jjsegmentedtotalbar(
    data = df_relab, x_var = "Gréade sc", y_var = "cnt", fill_var = "resp",
    show_statistical_tests = TRUE, y_is_count = TRUE, show_plot = FALSE
  ))
  expect_equal(res_relab$composition_table$asDF$percentage, c_base$percentage, tolerance = 1e-8)
  expect_equal(res_relab$statistical_tests$asDF$interpretation[2], "Highest positive association: G_III \u2192 Seg_H")

  # 3. Positive scale invariance of proportions under y -> 100 * y (y_is_count = FALSE)
  df_scale <- df
  df_scale$cnt <- df_scale$cnt * 100
  res_scale <- suppressWarnings(jjsegmentedtotalbar(
    data = df_scale, x_var = "Gréade sc", y_var = "cnt", fill_var = "resp",
    y_is_count = FALSE, show_plot = FALSE
  ))
  expect_equal(res_scale$composition_table$asDF$percentage, c_base$percentage, tolerance = 1e-8)
  expect_equal(res_scale$composition_table$asDF$overall_percentage, c_base$overall_percentage, tolerance = 1e-8)
  expect_equal(res_scale$summary$asDF$total_observations[1], 20000, tolerance = 1e-8)

  # 4. Row duplication homogeneity (X^2 scales by 2, standardized residual scales by sqrt(2))
  res_dup <- suppressWarnings(jjsegmentedtotalbar(
    data = rbind(df, df), x_var = "Gréade sc", y_var = "cnt", fill_var = "resp",
    show_statistical_tests = TRUE, y_is_count = TRUE, show_plot = FALSE
  ))
  expect_equal(res_dup$statistical_tests$asDF$statistic[1], 2 * t_base$statistic[1], tolerance = 1e-8)
  expect_equal(res_dup$statistical_tests$asDF$statistic[2], sqrt(2) * t_base$statistic[2], tolerance = 1e-8)

  # 5. Transpose symmetry (x_var <-> fill_var) for chi-square, p-value, and max |stdres|
  res_tr <- suppressWarnings(jjsegmentedtotalbar(
    data = df, x_var = "resp", y_var = "cnt", fill_var = "Gréade sc",
    show_statistical_tests = TRUE, y_is_count = TRUE, show_plot = FALSE
  ))
  expect_equal(res_tr$statistical_tests$asDF$statistic[1], t_base$statistic[1], tolerance = 1e-8)
  expect_equal(res_tr$statistical_tests$asDF$p_value[1], t_base$p_value[1], tolerance = 1e-8)
  expect_equal(res_tr$statistical_tests$asDF$statistic[2], t_base$statistic[2], tolerance = 1e-8)

  # 6. Facet subgroup consistency with subsetted un-faceted run
  hec_df <- as.data.frame(datasets::HairEyeColor)
  res_fac <- suppressWarnings(jjsegmentedtotalbar(
    data = hec_df, x_var = "Hair", y_var = "Freq", fill_var = "Eye",
    facet_var = "Sex", show_plot = FALSE
  ))
  res_male <- suppressWarnings(jjsegmentedtotalbar(
    data = subset(hec_df, Sex == "Male"), x_var = "Hair", y_var = "Freq",
    fill_var = "Eye", show_plot = FALSE
  ))
  c_fac <- res_fac$composition_table$asDF
  c_fac_male <- c_fac[grepl("\\[Male\\]$", c_fac$category), ]
  expect_equal(c_fac_male$percentage, res_male$composition_table$asDF$percentage, tolerance = 1e-8)
})

test_that("C03, C08, C23: boundary conditions (empty data, negative weights, NaN/Inf, integer-coded nominal factor)", {
  # Oracle: defensive input contracts and jmvcore nominal factor attributes
  df <- build_hand_fixture()

  # Empty data
  res_empty <- suppressWarnings(jjsegmentedtotalbar(
    data = df[0, ], x_var = "Gréade sc", y_var = "cnt", fill_var = "resp",
    show_plot = FALSE
  ))
  expect_equal(nrow(res_empty$composition_table$asDF), 0L)

  # Negative weights refused
  df_neg <- df
  df_neg$cnt[1] <- -5
  res_neg <- suppressWarnings(jjsegmentedtotalbar(
    data = df_neg, x_var = "Gréade sc", y_var = "cnt", fill_var = "resp",
    show_plot = FALSE
  ))
  expect_equal(nrow(res_neg$composition_table$asDF), 0L)

  # NaN and Inf dropped from y_var
  df_nonfin <- df
  df_nonfin$cnt[1] <- NaN
  df_nonfin$cnt[2] <- Inf
  res_nonfin <- suppressWarnings(jjsegmentedtotalbar(
    data = df_nonfin, x_var = "Gréade sc", y_var = "cnt", fill_var = "resp",
    show_plot = FALSE
  ))
  expect_equal(res_nonfin$summary$asDF$rows_analysed[1], 8L)

  # Integer-coded nominal factor with values attribute
  d_int_nom <- data.frame(
    arm  = factor(c(10, 10, 20, 20), levels = c(20, 10)),
    resp = factor(c(1, 2, 1, 2), levels = c(2, 1)),
    n    = c(30, 70, 80, 20)
  )
  attr(d_int_nom$arm, "values")  <- c(20L, 10L)
  attr(d_int_nom$resp, "values") <- c(2L, 1L)
  res_nom <- suppressWarnings(jjsegmentedtotalbar(
    data = d_int_nom, x_var = "arm", y_var = "n", fill_var = "resp",
    show_plot = FALSE
  ))
  tb_in <- res_nom$composition_table$asDF
  expect_equal(tb_in$percentage[tb_in$category == "20" & tb_in$segment == "2"], 0.20, tolerance = 1e-8)
})

