test_that("C18: Monte Carlo Type I error calibration under null independence (R = 300)", {
  # Oracle: multinomial independence null H0; nominal alpha = 0.05 within 3*SE = 0.0377
  set.seed(20260101)
  R_sim <- 300L
  p_vals <- numeric(R_sim)
  base_grid <- expand.grid(
    arm  = factor(c("A", "B", "C"), levels = c("A", "B", "C")),
    resp = factor(c("CR", "PR", "PD"), levels = c("CR", "PR", "PD"))
  )
  for (r in seq_len(R_sim)) {
    sim_df <- base_grid
    sim_df$n <- as.numeric(stats::rmultinom(1, size = 180, prob = rep(1 / 9, 9)))
    res_sim <- suppressWarnings(jjsegmentedtotalbar(
      data = sim_df, x_var = "arm", y_var = "n", fill_var = "resp",
      show_statistical_tests = TRUE, y_is_count = TRUE, show_plot = FALSE
    ))
    p_vals[r] <- res_sim$statistical_tests$asDF$p_value[1]
  }
  type1_rate <- mean(p_vals < 0.05)
  se_rate <- sqrt(0.05 * 0.95 / R_sim)
  expect_lte(abs(type1_rate - 0.05), 3 * se_rate)
})

test_that("C22, C23: clinical_summary prose, XSS escaping, and clinical readiness notice thresholds", {
  # Oracle: internal consistency with summary/composition_table and boundary thresholds in .validateClinicalData
  df <- build_hand_fixture()
  res <- suppressWarnings(jjsegmentedtotalbar(
    data = df, x_var = "Gréade sc", y_var = "cnt", fill_var = "resp",
    show_statistical_tests = TRUE, y_is_count = TRUE, show_plot = FALSE
  ))
  clin_txt <- strip_html(res$clinical_summary$content)
  expect_match(clin_txt, "examined 10 rows across 3 categories of Gréade sc", fixed = TRUE)
  expect_match(clin_txt, "(N=10 rows; total cnt = 200)", fixed = TRUE)
  expect_match(clin_txt, "High was the predominant segment in Stage III (60.0%)", fixed = TRUE)

  # XSS escaping in factor levels
  df_xss <- data.frame(
    cat = factor(c("<script>alert(1)</script>", "<script>alert(1)</script>", "Safe", "Safe")),
    seg = factor(c("<b>Pos</b>", "Neg", "<b>Pos</b>", "Neg")),
    cnt = c(10, 10, 15, 15)
  )
  res_xss <- suppressWarnings(jjsegmentedtotalbar(
    data = df_xss, x_var = "cat", y_var = "cnt", fill_var = "seg",
    show_plot = FALSE
  ))
  expect_false(grepl("<script>", res_xss$clinical_summary$content, fixed = TRUE))
  expect_true(grepl("&lt;script&gt;", res_xss$clinical_summary$content, fixed = TRUE))

  # Small Sample Size guard (< 5 vs >= 5)
  df_sm4 <- data.frame(cat = c("A", "A", "B", "B"), seg = c("S1", "S2", "S1", "S2"), cnt = c(2, 2, 10, 10))
  df_sm5 <- data.frame(cat = c("A", "A", "B", "B"), seg = c("S1", "S2", "S1", "S2"), cnt = c(2, 3, 10, 10))
  expect_match(
    strip_html(suppressWarnings(jjsegmentedtotalbar(data = df_sm4, x_var = "cat", y_var = "cnt", fill_var = "seg", show_plot = FALSE))$warnings$content),
    "Small Sample Size", fixed = TRUE
  )
  expect_false(grepl(
    "Small Sample Size",
    strip_html(suppressWarnings(jjsegmentedtotalbar(data = df_sm5, x_var = "cat", y_var = "cnt", fill_var = "seg", show_plot = FALSE))$warnings$content),
    fixed = TRUE
  ))

  # Extreme Proportions guard (> 95% vs <= 95%)
  df_ex95 <- data.frame(cat = c("A", "A", "B", "B"), seg = c("S1", "S2", "S1", "S2"), cnt = c(95, 5, 50, 50))
  df_ex96 <- data.frame(cat = c("A", "A", "B", "B"), seg = c("S1", "S2", "S1", "S2"), cnt = c(96, 4, 50, 50))
  expect_false(grepl(
    ">95%",
    strip_html(suppressWarnings(jjsegmentedtotalbar(data = df_ex95, x_var = "cat", y_var = "cnt", fill_var = "seg", show_plot = FALSE))$warnings$content),
    fixed = TRUE
  ))
  expect_match(
    strip_html(suppressWarnings(jjsegmentedtotalbar(data = df_ex96, x_var = "cat", y_var = "cnt", fill_var = "seg", show_plot = FALSE))$warnings$content),
    ">95%", fixed = TRUE
  )
})

test_that("C25, C27: plotTraditional bar heights, state-only rendering, and reference citations", {
  # Oracle: ggplot2::ggplot_build bar layer heights (0.50, 0.30, 0.20) and 00refs.yaml
  skip_if_not_installed("ggplot2")
  d_plot3 <- data.frame(
    cat = factor(c("A", "A", "A"), levels = "A"),
    seg = factor(c("S1", "S2", "S3"), levels = c("S1", "S2", "S3")),
    val = c(50, 30, 20)
  )
  opts_p3 <- ClinicoPath:::jjsegmentedtotalbarOptions$new(
    x_var = "cat", y_var = "val", fill_var = "seg",
    plot_type = "stacked", show_plot = TRUE
  )
  a_p3 <- ClinicoPath:::jjsegmentedtotalbarClass$new(options = opts_p3, data = d_plot3)
  suppressWarnings(a_p3$run())
  p_trad <- a_p3$.__enclos_env__$private$.plotTraditional(a_p3$results$plot$state$data, a_p3$results$plot, NULL, NULL)
  gb <- ggplot2::ggplot_build(p_trad)
  bar_layer <- gb$data[[1]]
  expect_equal(bar_layer$ymax - bar_layer$ymin, c(0.50, 0.30, 0.20), tolerance = 1e-8)

  # Render from image$state alone when private$.data is NULL
  saved_state <- a_p3$results$plot$state
  a_p3$.__enclos_env__$private$.data <- NULL
  a_p3$.__enclos_env__$private$.processed_data <- NULL
  a_p3$results$plot$setState(saved_state)
  png_tmp <- tempfile(fileext = ".png")
  grDevices::png(png_tmp, width = 400, height = 300)
  redraw_ok <- tryCatch(a_p3$.__enclos_env__$private$.plot(a_p3$results$plot, NULL, NULL), error = function(e) FALSE)
  grDevices::dev.off()
  unlink(png_tmp)
  expect_true(isTRUE(redraw_ok))
})

