                 levels = c("HighCount_33pct", "HighPct_90pct")),
    seg = factor(c("S1", "S2", "S3", "S1", "S2"), levels = c("S1", "S2", "S3")),
    n   = c(100, 100, 100, 90, 10)
  )
  res_lseg <- suppressWarnings(jjsegmentedtotalbar(
