test_that("VAL-jjsegmentedtotalbar-06 (C03, C06 / IR-08): missing-value handling respects facet_var and exclude_missing=FALSE", {
  df_fna <- data.frame(
    cat = factor(rep(c("A", "B"), each = 4)),
    seg = factor(rep(c("S1", "S2"), times = 4)),
    fac = factor(c("F1", "F1", "F1", "F1", "F2", "F2", NA, NA)),
    cnt = c(10, 20, 15, 25, 10, 20, 15, 25)
  )
  res_fna <- suppressWarnings(jjsegmentedtotalbar(
    data = df_fna, x_var = "cat", y_var = "cnt", fill_var = "seg",
    facet_var = "fac", exclude_missing = TRUE, show_plot = FALSE
  ))
  expect_equal(res_fna$summary$asDF$rows_analysed[1], 6L)

  d_ina <- data.frame(
    arm  = factor(c("A", "A", "B", "B", NA, NA)),
    resp = factor(c("CR", "PD", "CR", "PD", "CR", "PD")),
    n    = c(20, 10, 10, 20, 15, 15)
  )
  res_ina <- suppressWarnings(jjsegmentedtotalbar(
    data = d_ina, x_var = "arm", y_var = "n", fill_var = "resp",
    exclude_missing = FALSE, show_statistical_tests = TRUE, y_is_count = TRUE, show_plot = FALSE
  ))
  expect_false(any(is.na(res_ina$composition_table$asDF$category)))
  expect_true("(Missing)" %in% res_ina$composition_table$asDF$category)
  expect_equal(res_ina$statistical_tests$asDF$df[1], 2L)
})

