  opts_cnt <- stb_internal("jjsegmentedtotalbarOptions")$new(
    x_var = "Gréade sc", y_var = "cnt", fill_var = "resp",
    show_percentages = FALSE, show_counts = TRUE, show_plot = TRUE
  )
  a_cnt <- stb_internal("jjsegmentedtotalbarClass")$new(options = opts_cnt, data = df)
  suppressWarnings(a_cnt$run())
  p_cnt <- a_cnt$.__enclos_env__$private$.plotTraditional(a_cnt$results$plot$state$data, a_cnt$results$plot, NULL, NULL)
  expect_gte(length(p_cnt$layers), 2L)

  # color_palette = 'default' vs 'viridis'
