    x_var = "Gréade sc", y_var = "cnt", fill_var = "resp", color_palette = "default", show_plot = TRUE
  )
  a_def <- stb_internal("jjsegmentedtotalbarClass")$new(options = opts_def, data = df)
  suppressWarnings(a_def$run())
  p_def <- a_def$.__enclos_env__$private$.plotTraditional(a_def$results$plot$state$data, a_def$results$plot, NULL, NULL)

  opts_vir <- stb_internal("jjsegmentedtotalbarOptions")$new(
