  ))
})

test_that("VAL-jjsegmentedtotalbar-10 (IR-05, IR-06, IR-11, IR-14): uniform null prose, stale-state clearing, CMH stratification, temporal warning, and Haberman explanation", {
  # 1. Exact uniform null table (IR-05)
  d_null <- data.frame(
    arm  = factor(c("ArmA", "ArmA", "ArmB", "ArmB"), levels = c("ArmA", "ArmB")),
    resp = factor(c("CR", "PR", "CR", "PR"), levels = c("CR", "PR")),
    cnt  = c(50, 50, 50, 50)
  )
  res_null <- suppressWarnings(jjsegmentedtotalbar(
    data = d_null, x_var = "arm", y_var = "cnt", fill_var = "resp",
    show_statistical_tests = TRUE, y_is_count = TRUE, showExplanations = TRUE, show_plot = FALSE
  ))
  null_clin <- strip_html(res_null$clinical_summary$content)
  expect_false(grepl("Distribution patterns varied across categories", null_clin, fixed = TRUE))
  expect_match(null_clin, "uniform across all categories", fixed = TRUE)
  expect_match(strip_html(res_null$explanations$content), "Haberman (1973)", fixed = TRUE)

  # 2. Stale-state clearing on valid -> invalid transition on reused R6 instance (IR-06)
  d_cont <- data.frame(
    arm = factor(c("A", "A", "B", "B")),
    seg = factor(c("x", "y", "x", "y")),
    val = c(1.25, 2.25, 3.50, 4.50)
  )
  opts_trans <- stb_internal("jjsegmentedtotalbarOptions")$new(
    x_var = "arm", y_var = "val", fill_var = "seg", y_is_count = FALSE, show_plot = TRUE
  )
  a_trans <- stb_internal("jjsegmentedtotalbarClass")$new(options = opts_trans, data = d_cont)
  suppressWarnings(a_trans$run())
  opts_trans$.__enclos_env__$private$..y_is_count$.__enclos_env__$private$.value <- TRUE
  suppressWarnings(a_trans$run())
  expect_true(is.na(a_trans$results$summary$asDF$total_observations[1]))
  expect_null(a_trans$results$plot$state)
  expect_equal(strip_html(a_trans$results$clinical_summary$content), "")

  # 3. Simpson's paradox prevention via CMH stratification under facet_var (IR-11)
  d_simpson <- data.frame(
    arm  = factor(c("ArmA", "ArmA", "ArmB", "ArmB", "ArmA", "ArmA", "ArmB", "ArmB"), levels = c("ArmA", "ArmB")),
    resp = factor(c("CR", "NR", "CR", "NR", "CR", "NR", "CR", "NR"), levels = c("CR", "NR")),
    site = factor(c("Site1", "Site1", "Site1", "Site1", "Site2", "Site2", "Site2", "Site2")),
    n    = c(10, 90, 2, 18, 18, 2, 90, 10)
  )
  res_simp <- suppressWarnings(jjsegmentedtotalbar(
    data = d_simpson, x_var = "arm", y_var = "n", fill_var = "resp", facet_var = "site",
    show_statistical_tests = TRUE, y_is_count = TRUE, show_plot = FALSE
  ))
  st_simp <- res_simp$statistical_tests$asDF
  expect_equal(st_simp$test_name[1], "Cochran-Mantel-Haenszel")
  expect_equal(st_simp$statistic[1], 0, tolerance = 1e-8)
  expect_equal(st_simp$p_value[1], 1, tolerance = 1e-8)
  expect_equal(nrow(st_simp), 3L)

  # 4. Repeated-measures caution on temporal preset with statistical tests enabled (IR-11)
  res_temp <- suppressWarnings(jjsegmentedtotalbar(
    data = build_hand_fixture(), x_var = "Gréade sc", y_var = "cnt", fill_var = "resp",
    analysis_preset = "temporal", show_statistical_tests = TRUE, y_is_count = TRUE, show_plot = FALSE
  ))
  expect_match(strip_html(res_temp$warnings$content), "Repeated-measures caution", fixed = TRUE)
})

test_that("VAL-jjsegmentedtotalbar-11 (Release Profile): reserved column names, special characters, and duplicate variables are safe", {
  df_reserved <- data.frame(
    count = factor(rep(c("Arm 1", "Arm 2"), each = 4)),
    value = factor(rep(c("CR", "PD"), times = 4)),
    group = factor(rep(c("Site A", "Site B"), each = 2, times = 2)),
    total = c(12, 8, 15, 5, 6, 14, 7, 13),
    check.names = FALSE
  )

  res_res <- suppressWarnings(jjsegmentedtotalbar(
    data = df_reserved,
    x_var = "count",
    y_var = "total",
    fill_var = "value",
    facet_var = "group",
    show_plot = TRUE,
    plot_type = "flerlage",
    flerlage_show_labels = TRUE,
    y_is_count = TRUE,
    show_statistical_tests = TRUE
  ))

  expect_equal(nrow(res_res$composition_table$asDF), 8L)
  expect_true(nrow(res_res$statistical_tests$asDF) >= 1L)
  p_res <- render_plot_obj(res_res)
  expect_s3_class(p_res, "ggplot")

  df_special <- data.frame(
    `Age (years)` = factor(c("<65", "<65", ">=65", ">=65")),
    `Grade A+B` = factor(c("Low-1", "High/2", "Low-1", "High/2")),
    `BMI-1` = c(25, 15, 10, 30),
    check.names = FALSE
  )
  res_sp <- suppressWarnings(jjsegmentedtotalbar(
    data = df_special,
    x_var = "Age (years)",
    y_var = "BMI-1",
    fill_var = "Grade A+B",
    show_plot = TRUE,
    y_is_count = TRUE,
    show_statistical_tests = TRUE
  ))
  expect_equal(nrow(res_sp$composition_table$asDF), 4L)
  expect_equal(nrow(res_sp$statistical_tests$asDF), 1L)

  # Duplicate variable assignment returns friendly ERROR notice instead of crashing
  res_dup <- suppressWarnings(jjsegmentedtotalbar(
    data = df_reserved,
    x_var = "count",
    y_var = "total",
    fill_var = "count"
  ))
  expect_match(strip_html(res_dup$warnings$content), "distinct", fixed = TRUE)
  expect_equal(nrow(res_dup$composition_table$asDF), 0L)
})

test_that("VAL-jjsegmentedtotalbar-12 (Release Profile): labelled variables, global jamovi theme/palette, Flerlage sub-4 totals, and declarative visibility", {
  # 1. Labelled numeric value labels + variable label attributes via R6 class directly
  arm_lbl <- c(1, 1, 2, 2)
  attr(arm_lbl, "labels") <- c("Control Arm" = 1, "Experimental Arm" = 2)
  attr(arm_lbl, "label") <- "Clinical Study Arm"

  resp_lbl <- c(10, 20, 10, 20)
  attr(resp_lbl, "labels") <- c("Responder" = 10, "Non-Responder" = 20)
  attr(resp_lbl, "label") <- "RECIST Outcome"

  df_lbl <- data.frame(arm = arm_lbl, resp = resp_lbl, n = c(18, 12, 24, 6))
  opts_lbl <- stb_internal("jjsegmentedtotalbarOptions")$new(
    x_var = "arm",
    y_var = "n",
    fill_var = "resp",
    show_plot = TRUE,
    chart_style = "jamovi",
    color_palette = "jamovi"
  )
  ana_lbl <- stb_internal("jjsegmentedtotalbarClass")$new(options = opts_lbl, data = df_lbl)
  ana_lbl$run()

  comp_df <- ana_lbl$results$composition_table$asDF
  expect_equal(unique(comp_df$category), c("Control Arm", "Experimental Arm"))
  expect_equal(unique(comp_df$segment), c("Responder", "Non-Responder"))
  p_lbl <- render_plot_obj(ana_lbl$results)
  expect_equal(p_lbl$labels$x, "Clinical Study Arm")
  expect_equal(p_lbl$labels$fill, "RECIST Outcome")

  # 2. Flerlage plot with small total in [1, 4) (e.g. 1.2) does not clip bars via ylim(0, 1)
  df_sub4 <- data.frame(
    g = factor(c("A", "A", "B", "B")),
    s = factor(c("S1", "S2", "S1", "S2")),
    v = c(0.7, 0.5, 0.4, 0.4)
  )
  res_sub4 <- suppressWarnings(jjsegmentedtotalbar(
    data = df_sub4,
    x_var = "g",
    y_var = "v",
    fill_var = "s",
    show_plot = TRUE,
    plot_type = "flerlage",
    flerlage_show_labels = TRUE
  ))
  p_sub4 <- render_plot_obj(res_sub4)
  built_sub4 <- ggplot2::ggplot_build(p_sub4)
  expect_false(any(is.na(built_sub4$data[[1]]$ymax)))

  # 3. Declarative visibility & welcome instructions
  opts_empty <- stb_internal("jjsegmentedtotalbarOptions")$new()
  ana_empty <- stb_internal("jjsegmentedtotalbarClass")$new(options = opts_empty, data = df_sub4)
  ana_empty$init()
  expect_true(ana_empty$results$instructions$visible)
  expect_match(strip_html(ana_empty$results$instructions$content), "Setup Progress", fixed = TRUE)
  expect_false(ana_empty$results$plot$visible)
  expect_false(ana_empty$results$statistical_tests$visible)
  expect_false(ana_empty$results$preset_guidance$visible)
  expect_false(ana_empty$results$explanations$visible)

  res_vis <- suppressWarnings(jjsegmentedtotalbar(
    data = df_sub4,
    x_var = "g",
    y_var = "v",
    fill_var = "s",
    analysis_preset = "biomarker",
    show_plot = TRUE,
    showExplanations = TRUE
  ))
  expect_false(res_vis$instructions$visible)
  expect_true(res_vis$plot$visible)
  expect_true(res_vis$preset_guidance$visible)
  expect_true(res_vis$explanations$visible)
})

